/**
 * Tool Dispatcher: every ork PreToolUse handler in one process.
 *
 * yellow-refactor M1, phase 1. Shipped hooks.json starts 3 PreToolUse
 * processes for Bash, Write, Edit and Read (the per-tool sync dispatcher plus
 * lifecycle/webhook-forwarder twice, once from the per-tool group and once
 * from the matcher-less group). This handler replaces all of them with one
 * matcher-less entry: it routes by tool_name to the same handlers, in the
 * same order, and forwards the event exactly once.
 *
 * OFF by default. It is wired only into the hooks.json variant written by
 * scripts/unified-pretool-hooks.mjs; the shipped hooks.json never names it.
 *
 * Contract:
 * - The route's primary (sync) handler result is returned unchanged, so a
 *   deny, ask, defer or updatedInput reaches CC exactly as today.
 * - Observers (today registered async) run after the primary handler; their
 *   results are ignored and a throw never changes the verdict.
 * - The webhook forward runs last and is isolated the same way.
 */

import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { syncBashDispatcher } from './bash/sync-bash-dispatcher.js';
import { syncWriteEditDispatcher } from './write-edit/sync-write-edit-dispatcher.js';
import { tldrSummary } from './read/tldr-summary.js';
import { syncTaskDispatcher } from './task/sync-task-dispatcher.js';
import { routeObserver } from './task/route-observer.js';
import { skillTracker } from './skill/skill-tracker.js';
import { context7Tracker } from './mcp/context7-tracker.js';
import { memoryValidator } from './mcp/memory-validator.js';
import headlessResponder from './ask/headless-responder.js';
import { workflowAgentTypeAdvisor } from './task/workflow-agenttype-advisor.js';
import { webhookForwarder } from '../lifecycle/webhook-forwarder.js';

const HOOK_NAME = 'tool-dispatcher';

type Fn = (input: HookInput, ctx: HookContext) => HookResult | Promise<HookResult>;

interface Route {
  /** True when this route owns the tool. */
  match: (tool: string) => boolean;
  /** Handler ids as named in hooks.json, primary first (for the coverage test). */
  handlers: string[];
  /** Sync handler whose result is the hook result; absent for observe-only routes. */
  primary?: Fn;
  /** Handlers that were async in hooks.json: run after, result ignored. */
  observers: Fn[];
}

const exact = (...names: string[]) => (tool: string) => names.includes(tool);
const prefix = (p: string) => (tool: string) => tool.startsWith(p);

/**
 * Mirrors the PreToolUse groups of src/hooks/hooks.json (2026-10-31).
 * The mcp groups use matchers "mcp__context7__*" and "mcp__memory__*"; their
 * intent is a prefix match, which is what is routed here.
 */
export const PRETOOL_ROUTES: Route[] = [
  { match: exact('Bash'), handlers: ['pretool/bash/sync-bash-dispatcher'], primary: syncBashDispatcher, observers: [] },
  {
    match: exact('Write', 'Edit'),
    handlers: ['pretool/write-edit/sync-write-edit-dispatcher'],
    primary: syncWriteEditDispatcher,
    observers: [],
  },
  { match: exact('Read'), handlers: ['pretool/read/tldr-summary'], primary: tldrSummary, observers: [] },
  {
    match: exact('Agent'),
    handlers: ['pretool/task/sync-task-dispatcher', 'pretool/task/route-observer'],
    primary: syncTaskDispatcher,
    observers: [routeObserver],
  },
  { match: exact('Skill'), handlers: ['pretool/skill/skill-tracker'], observers: [skillTracker] },
  { match: prefix('mcp__context7__'), handlers: ['pretool/mcp/context7-tracker'], primary: context7Tracker, observers: [] },
  { match: prefix('mcp__memory__'), handlers: ['pretool/mcp/memory-validator'], primary: memoryValidator, observers: [] },
  { match: exact('AskUserQuestion'), handlers: ['pretool/ask/headless-responder'], primary: headlessResponder, observers: [] },
  {
    match: exact('Workflow'),
    handlers: ['pretool/task/workflow-agenttype-advisor'],
    primary: workflowAgentTypeAdvisor,
    observers: [],
  },
];

async function isolated(name: string, fn: Fn, input: HookInput, ctx: HookContext): Promise<void> {
  try {
    await fn(input, ctx);
  } catch (err) {
    ctx.log(HOOK_NAME, `${name} failed (isolated): ${err instanceof Error ? err.message : String(err)}`);
  }
}

export async function toolDispatcher(input: HookInput, ctx: HookContext = NOOP_CTX): Promise<HookResult> {
  const tool = input.tool_name ?? '';
  const route = PRETOOL_ROUTES.find((r) => r.match(tool));

  let result: HookResult = outputSilentSuccess();
  try {
    if (route?.primary) result = await route.primary(input, ctx);
  } finally {
    for (const [i, observer] of (route?.observers ?? []).entries()) {
      await isolated(route?.handlers[i + (route.primary ? 1 : 0)] ?? 'observer', observer, input, ctx);
    }
    await isolated('lifecycle/webhook-forwarder', webhookForwarder, input, ctx);
  }
  return result;
}
